package edu.pbs.hub.controller; import edu.pbs.hub.model.*;import edu.pbs.hub.repo.*;import edu.pbs.hub.config.AdminGuard;import org.springframework.web.bind.annotation.*;import jakarta.servlet.http.HttpServletRequest;import java.util.*;
@RestController @RequestMapping("/api/courses") public class CourseController {private final CourseRepository repo;private final AdminGuard guard;public CourseController(CourseRepository r,AdminGuard g){repo=r;guard=g;} @GetMapping public List<Course> list(){return repo.findByActiveTrueOrderByNameAsc();} @PostMapping public Course add(@RequestBody Course c,HttpServletRequest q){guard.check(q);return repo.save(c);} @PutMapping("/{id}") public Course edit(@PathVariable Long id,@RequestBody Course c,HttpServletRequest q){guard.check(q);Course x=repo.findById(id).orElseThrow();x.setName(c.getName());x.setShortName(c.getShortName());x.setDepartment(c.getDepartment());x.setDescription(c.getDescription());x.setActive(c.isActive());return repo.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id,HttpServletRequest q){guard.check(q);repo.deleteById(id);} }
